param([string]$ManifestPath="docs/etc/cpu-timing/t435-s2-80386-timing-manifest.json")
$ErrorActionPreference="Stop"
function Expand-Template($t){$keys=@($t.id);foreach($p in $t.PSObject.Properties){if($p.Name -in @("id","level","source_rule","route","status","batch","test")){continue};if($p.Value -isnot [System.Array]){continue};$next=@();foreach($k in $keys){foreach($v in $p.Value){$next+=$k.Replace("{"+$p.Name+"}",[string]$v)}};$keys=$next};$keys}
if(-not(Test-Path -LiteralPath $ManifestPath)){throw "Manifest not found"};$m=Get-Content -Raw -LiteralPath $ManifestPath|ConvertFrom-Json;if($m.schema -ne "nxvm.cpu-timing-manifest.v1" -or $m.profile -ne "80386DX"){throw "Unexpected manifest"}
$seen=@{};$c=@{L3=0;conforming=0;'wrong-value'=0;unallocated=0;'missing-input'=0;'missing-test'=0};foreach($t in $m.base_templates){foreach($f in @("id","level","source_rule","route","status","batch","test")){if([string]::IsNullOrWhiteSpace([string]$t.$f)){throw "Missing $f"}};if($t.level -ne "L3"){throw "Non-L3 key"};foreach($k in Expand-Template $t){if($seen.ContainsKey($k)){throw "Duplicate key $k"};$seen[$k]=$true;++$c.L3;++$c[[string]$t.status]}}
if($seen.Count -ne $m.expected.base -or $c.L3 -ne $m.expected.L3){throw "Count mismatch"};$contexts=@{};foreach($set in $m.context_key_sets){foreach($f in @("id_suffix","base_selector","source_rule","route","status","batch","test")){if([string]::IsNullOrWhiteSpace([string]$set.$f)){throw "Context missing $f"}};$suffixes=@($set.id_suffix);if($null -ne $set.phase){$suffixes=@($set.phase|ForEach-Object{$set.id_suffix.Replace("{phase}",[string]$_)})};if($null -ne $set.kind){$suffixes=@($set.kind|ForEach-Object{$set.id_suffix.Replace("{kind}",[string]$_)})};$rx=[regex]$set.base_selector;foreach($b in $seen.Keys){if(-not $rx.IsMatch($b)){continue};foreach($s in $suffixes){$k="$b-$s";if($contexts.ContainsKey($k)){throw "Duplicate context $k"};$contexts[$k]=$true}}};"80386DX timing manifest: base=$($seen.Count) L3=$($c.L3) conforming=$($c.conforming) wrong=$($c['wrong-value']) unallocated=$($c.unallocated) missing_input=$($c['missing-input']) missing_test=$($c['missing-test']) contexts=$($contexts.Count)"
